# Complete finite support helper, retained verbatim from the existing scene helper.
"""Full finite polygon set subtraction; no point-grid support approximation."""
import numpy as np

def area(p):
 return abs(sum(float(np.cross(p[i],p[(i+1)%len(p)])) for i in range(len(p))))/2 if len(p)>=3 else 0.
def signed_area(p):return sum(float(np.cross(p[i],p[(i+1)%len(p)])) for i in range(len(p)))/2

def halfclip(poly,a,b,inside=True,eps=1e-12):
 if not len(poly):return []
 sign=1 if inside else -1;out=[];p=poly[-1];dp=sign*float(np.cross(b-a,p-a))
 for q in poly:
  dq=sign*float(np.cross(b-a,q-a));ip=dp>=-eps;iq=dq>=-eps
  if ip!=iq:out.append(p+(q-p)*(dp/(dp-dq)))
  if iq:out.append(q)
  p=q;dp=dq
 return out

def subtract(poly,clip):
 poly=[np.array(p,dtype=float) for p in poly];clip=np.array(clip,dtype=float)
 if signed_area(clip)<0:clip=clip[::-1]
 kept=poly;out=[]
 for a,b in zip(clip,np.roll(clip,-1,axis=0)):
  outside=halfclip(kept,a,b,False);kept=halfclip(kept,a,b,True)
  if area(outside)>1e-14:out.append(outside)
  if area(kept)<=1e-14:break
 return out

def remainder(polys,clips):
 pieces=[[np.array(v,dtype=float) for v in p] for p in polys]
 for clip in clips:
  clo,chi=np.min(clip,axis=0),np.max(clip,axis=0);out=[]
  for p in pieces:
   if np.any(np.max(p,axis=0)<clo-1e-12) or np.any(np.min(p,axis=0)>chi+1e-12):out.append(p)
   else:out.extend(subtract(p,clip))
  pieces=out
 return pieces

def rect(x0,x1,y0,y1):return np.array([[x0,y0],[x1,y0],[x1,y1],[x0,y1]],dtype=float)

def intersect(poly,clip):
 p=[np.array(x,dtype=float) for x in poly];c=np.array(clip,dtype=float)
 if signed_area(c)<0:c=c[::-1]
 for a,b in zip(c,np.roll(c,-1,axis=0)):
  p=halfclip(p,a,b)
  if len(p)<3:return []
 return p

def segment_convex_interval(a,b,poly,eps=0.):
 p=np.array(poly,dtype=float)
 if signed_area(p)<0:p=p[::-1]
 lo,hi=0.,1.;v=b-a
 for c,d in zip(p,np.roll(p,-1,axis=0)):
  n=np.array([-(d-c)[1],(d-c)[0]]);n/=np.linalg.norm(n);q=float(np.dot(n,a-c))+eps;s=float(np.dot(n,v))
  if abs(s)<1e-18:
   if q<0:return None
  elif s>0:lo=max(lo,-q/s)
  else:hi=min(hi,-q/s)
  if lo>hi:return None
 return [max(0.,lo),min(1.,hi)]

def disk_interval(a,b,c,r):
 v=b-a;q=a-c;aa=float(v@v);bb=2*float(q@v);cc=float(q@q-r*r)
 if aa<1e-30:return [0.,1.] if cc<=0 else None
 disc=bb*bb-4*aa*cc
 if disc<0:return None
 root=np.sqrt(max(0,disc));lo=max(0.,(-bb-root)/(2*aa));hi=min(1.,(-bb+root)/(2*aa));return [lo,hi] if hi>=lo else None

def segment_covered(a,b,polys,tol=2e-7):
 """Exact union of segment intervals in polygon interiors, edge strips and vertex disks.
 The strips/disks are precisely the Euclidean tol-neighbourhood, not an
 unbounded shifted-halfspace approximation at sharp corners.
 """
 a=np.array(a);b=np.array(b);intervals=[]
 for poly in polys:
  p=np.array(poly)
  if np.any(np.maximum(a,b)<p.min(0)-tol) or np.any(np.minimum(a,b)>p.max(0)+tol):continue
  v=segment_convex_interval(a,b,p)
  if v:intervals.append(v)
  for c,d in zip(p,np.roll(p,-1,axis=0)):
   delta=d-c;length=np.linalg.norm(delta)
   if length<1e-15:continue
   n=np.array([-delta[1],delta[0]])/length*tol;strip=np.array([c+n,d+n,d-n,c-n]);v=segment_convex_interval(a,b,strip)
   if v:intervals.append(v)
   v=disk_interval(a,b,c,tol)
   if v:intervals.append(v)
 intervals.sort();end=0.
 for lo,hi in intervals:
  if lo>end+1e-11:return False
  end=max(end,hi)
  if end>=1-1e-11:return True
 return False

def cover_full(polys,clips,tol=2e-7,area_tol=2e-7,label='finite cover'):
 assert clips,(label,'no actual support polygons')
 rem=remainder(polys,clips);uncovered=sum(area(p) for p in rem)
 assert uncovered<=area_tol,(label,'uncovered area',uncovered)
 vertices=edges=0
 # Check both original boundaries and all subtracted residual boundaries.
 # Thus a tiny-area, long distant sliver cannot pass an area-only threshold.
 for p in list(polys)+rem:
  for a,b in zip(p,np.roll(p,-1,axis=0)):
   assert segment_covered(np.array(a),np.array(a),clips,tol),(label,'uncovered finite vertex',np.array(a).tolist())
   assert segment_covered(np.array(a),np.array(b),clips,tol),(label,'uncovered complete edge',np.array(a).tolist(),np.array(b).tolist())
   vertices+=1;edges+=1
 return {'uncovered_area_m2':uncovered,'all_vertices_checked':vertices,'all_complete_edges_checked':edges,'space_tolerance_m':tol,'area_tolerance_m2':area_tol,'method':'Complete polygon subtraction plus exact full-edge parameter-interval union in the Euclidean tolerance neighbourhood of all finite support polygons'}

